<?php
namespace Tests\Feature;
use App\Models\{ZigoDeployment,ZigoDeploymentFile,ZigoDeploymentLog,ZigoDevOpsAlert};use App\Services\DevOps\{ReleaseService,EnvironmentComparisonService,DeploymentDriftService,DevOpsAlertService,DevOpsAuditService,DeploymentTimelineViewModel,PromotionEligibilityService,DevOpsReportService};use Illuminate\Database\Schema\Blueprint;use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Schema};use Tests\TestCase;
final class DevOpsEnterpriseTest extends TestCase {
 protected function setUp():void{parent::setUp();config(['database.default'=>'sqlite','database.connections.sqlite'=>['driver'=>'sqlite','database'=>':memory:','prefix'=>'','foreign_key_constraints'=>true],'zigo_devops.allow_production'=>false]);DB::purge('sqlite');DB::reconnect('sqlite');Schema::create('users',fn(Blueprint $t)=>$t->id());Schema::create('zigo_deployments',function(Blueprint$t){$t->id();$t->string('environment');$t->string('package_name');$t->string('branch')->nullable();$t->string('commit_hash')->nullable();$t->string('package_sha256');$t->string('status');$t->unsignedBigInteger('requested_by_user_id')->nullable();$t->unsignedBigInteger('approved_by_user_id')->nullable();$t->timestamp('started_at')->nullable();$t->timestamp('finished_at')->nullable();$t->string('backup_path')->nullable();$t->boolean('rollback_available')->default(false);$t->text('summary')->nullable();$t->timestamps();});Schema::create('zigo_deployment_files',function(Blueprint$t){$t->id();$t->unsignedBigInteger('deployment_id');$t->string('relative_path');$t->boolean('existed_before');$t->string('backup_fingerprint')->nullable();$t->string('deployed_fingerprint')->nullable();$t->timestamps();});Schema::create('zigo_deployment_logs',function(Blueprint$t){$t->id();$t->unsignedBigInteger('deployment_id');$t->string('level');$t->string('step');$t->text('message');$t->timestamp('created_at')->nullable();});Schema::create('zigo_health_checks',function(Blueprint$t){$t->id();$t->string('environment');$t->string('check_key');$t->string('status');$t->integer('http_status')->nullable();$t->integer('duration_ms')->nullable();$t->string('message')->nullable();$t->unsignedBigInteger('checked_by_user_id')->nullable();$t->timestamp('checked_at');$t->timestamps();});Schema::create('zigo_devops_releases',function(Blueprint$t){$t->id();$t->string('environment');$t->unsignedBigInteger('deployment_id');$t->string('branch')->nullable();$t->string('commit_hash')->nullable();$t->string('package_sha256');$t->string('status');$t->timestamp('deployed_at');$t->unsignedBigInteger('deployed_by_user_id')->nullable();$t->string('files_fingerprint')->nullable();$t->json('metadata')->nullable();$t->timestamps();});Schema::create('zigo_devops_alerts',function(Blueprint$t){$t->id();$t->string('type');$t->string('severity');$t->string('environment')->nullable();$t->unsignedBigInteger('deployment_id')->nullable();$t->string('title');$t->text('message');$t->string('status');$t->unsignedBigInteger('acknowledged_by_user_id')->nullable();$t->timestamp('acknowledged_at')->nullable();$t->json('metadata')->nullable();$t->timestamps();});Schema::create('zigo_devops_audits',function(Blueprint$t){$t->id();$t->unsignedBigInteger('user_id')->nullable();$t->string('action');$t->string('environment')->nullable();$t->unsignedBigInteger('deployment_id')->nullable();$t->string('result');$t->string('ip_hash')->nullable();$t->string('user_agent_hash')->nullable();$t->json('metadata')->nullable();$t->timestamp('created_at')->nullable();});}
 private function deployment(string $env,string $commit='abc'):ZigoDeployment{$d=ZigoDeployment::create(['environment'=>$env,'package_name'=>'release','branch'=>'main','commit_hash'=>$commit,'package_sha256'=>str_repeat('a',64),'status'=>'success','started_at'=>now()->subSecond(),'finished_at'=>now(),'rollback_available'=>true]);ZigoDeploymentFile::create(['deployment_id'=>$d->id,'relative_path'=>'app/Test.php','existed_before'=>true,'deployed_fingerprint'=>hash('sha256','ok')]);return$d;}
 public function test_release_active_history_and_synchronized_comparison():void{$s=$this->deployment('stage');$p=$this->deployment('production');$service=app(ReleaseService::class);$first=$service->register($s);$second=$service->register($this->deployment('stage','def'));$service->register($p);$this->assertSame('superseded',$first->refresh()->status);$this->assertSame($second->id,$service->active('stage')->id);$this->assertSame('synchronized',app(EnvironmentComparisonService::class)->compare()['status']);}
 public function test_drift_modified_and_missing():void{$d=$this->deployment('stage');$release=app(ReleaseService::class)->register($d);$root=storage_path('framework/testing-devops');if(!is_dir($root.'/app'))mkdir($root.'/app',0777,true);config(['zigo_devops.paths.stage'=>$root]);file_put_contents($root.'/app/Test.php','changed');$this->assertSame('modified',app(DeploymentDriftService::class)->inspect($release,true)['status']);unlink($root.'/app/Test.php');$this->assertSame('missing',app(DeploymentDriftService::class)->inspect($release,true)['status']);}
 public function test_alert_audit_hash_timeline_reports_and_promotion_block():void{$d=$this->deployment('stage');$alert=app(DevOpsAlertService::class)->create('deployment_failed','critical','Failed','Safe message','stage',$d);$this->assertSame('open',$alert->status);$request=Request::create('/','GET',[],[],[],['REMOTE_ADDR'=>'192.0.2.1','HTTP_USER_AGENT'=>'secret-agent']);$audit=app(DevOpsAuditService::class)->record('upload','success','stage',$d->id,['token'=>'secret'],$request);$this->assertNotSame('192.0.2.1',$audit->ip_hash);$this->assertSame('[REDACTED]',$audit->metadata['token']);ZigoDeploymentLog::create(['deployment_id'=>$d->id,'level'=>'info','step'=>'upload','message'=>'Uploaded','created_at'=>now()]);$timeline=app(DeploymentTimelineViewModel::class)->build($d);$this->assertSame('completed',collect($timeline)->firstWhere('step','upload')['result']);app(ReleaseService::class)->register($d);$this->assertFalse(app(PromotionEligibilityService::class)->evaluate()['eligible']);$this->assertSame(1,app(DevOpsReportService::class)->metrics()['open_alerts']);}
}
